    ["GetTrainerServiceDescription(1)"] = "1: string Stuns the target for 2 sec.",
    ["GetTrainerServiceDescription(10)"] = "1: string Burns the enemy for 15 to 19 Arcane damage and then an additional 24 Arcane damage over 12 sec.",
    ["GetTrainerServiceDescription(100)"] = "1: string Increases the target's Mana regeneration by 400% and allows 100% of the target's Mana regeneration to continue while casting.  Lasts 20 sec.",
    ["GetTrainerServiceDescription(101)"] = "1: string The enemy target is swarmed by insects, decreasing their chance to hit with attacks by 2% and causing 120 Nature damage over 12 sec.",
    ["GetTrainerServiceDescription(102)"] = "1: string Increases the friendly target's armor by 263, all attributes by 11 and all resistances by 14 for 1 |4hour:hrs;.",
    ["GetTrainerServiceDescription(103)"] = "1: string Burns the enemy for 67 to 79 Arcane damage and then an additional 124 Arcane damage over 12 sec.",
    ["GetTrainerServiceDescription(104)"] = "1: string Allows the Druid to prowl around, but reduces your movement speed by 35%.  Lasts until cancelled.",
    ["GetTrainerServiceDescription(105)"] = "1: string Returns the spirit to the body, restoring a dead target to life with 1,100 health and 1700 mana.",
    ["GetTrainerServiceDescription(106)"] = "1: string Heals the target for 284 over 12 sec.",
    ["GetTrainerServiceDescription(107)"] = "1: string Regenerates all nearby party members within 20 yards for 129 every 2 sec for 10 sec.  Druid must channel to maintain the spell.",
    ["GetTrainerServiceDescription(108)"] = "1: string The druid roars, decreasing nearby enemies' melee attack power by 144.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(109)"] = "1: string Decrease the armor of the target by 395 for 40 sec.  While affected, the target cannot stealth or turn invisible.",
    ["GetTrainerServiceDescription(11)"] = "1: string Burns the enemy for 21 to 25 Arcane damage and then an additional 36 Arcane damage over 12 sec.",
    ["GetTrainerServiceDescription(110)"] = "1: string Lacerates the enemy target, making them bleed for 50 damage over 15 sec plus 10% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target.",
    ["GetTrainerServiceDescription(111)"] = "1: string Increases the druid's next attack by 78 damage.",
    ["GetTrainerServiceDescription(112)"] = "1: string Ravage the target, causing 350% damage plus 217 to the target.  Must be prowling and behind the target.  Awards 1 combo point.",
    ["GetTrainerServiceDescription(113)"] = "1: string Heals a friendly target for 474 to 534 and another 476 over 21 sec.",
    ["GetTrainerServiceDescription(114)"] = "1: string Causes 181 to 215 Arcane damage to the target.",
    ["GetTrainerServiceDescription(115)"] = "1: string Your skin becomes as tough as bark. Physical damage taken is reduced by 20%. While you are protected, damaging attacks will not cause spellcasting delays. Lasts 15 sec.",
    ["GetTrainerServiceDescription(116)"] = "1: string Heals a friendly target for 1,071 to 1,275.",
    ["GetTrainerServiceDescription(117)"] = "1: string Rake the target for 49 damage and an additional 85 damage over 9 sec.  Awards 1 combo point.",
    ["GetTrainerServiceDescription(118)"] = "1: string Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\r\n   1 point  : 124 damage over 12 sec.\r\n   2 points: 200 damage over 12 sec.\r\n   3 points: 277 damage over 12 sec.\r\n   4 points: 353 damage over 12 sec.\r\n   5 points: 429 damage over 12 sec.",
    ["GetTrainerServiceDescription(119)"] = "1: string Swipe 3 nearby enemies, inflicting 66 damage.",
