    ["GetTrainerServiceDescription(174)"] = "1: string Increases the friendly target's armor by 385, all attributes by 16 and all resistances by 27 for 1 |4hour:hrs;.",
    ["GetTrainerServiceDescription(175)"] = "1: string Bite the target, dealing 100% normal damage plus 77 and generating a high amount of threat.",
    ["GetTrainerServiceDescription(176)"] = "1: string Allows the Druid to prowl around, but reduces your movement speed by 30%.  Lasts until cancelled.",
    ["GetTrainerServiceDescription(177)"] = "1: string Returns the spirit to the body, restoring a dead target to life with 2,200 health and 2800 mana.",
    ["GetTrainerServiceDescription(178)"] = "1: string Heals a friendly target for 965 to 1,077 and another 994 over 21 sec.",
    ["GetTrainerServiceDescription(179)"] = "1: string Brings a dead player back to life with 750 health and 1000 mana. Cannot be cast when in combat.",
    ["GetTrainerServiceDescription(18)"] = "1: string Swipe 3 nearby enemies, inflicting 19 damage.",
    ["GetTrainerServiceDescription(180)"] = "1: string Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\r\n   1 point  : 243 damage over 12 sec.\r\n   2 points: 396 damage over 12 sec.\r\n   3 points: 549 damage over 12 sec.\r\n   4 points: 702 damage over 12 sec.\r\n   5 points: 855 damage over 12 sec.\r\n",
    ["GetTrainerServiceDescription(181)"] = "1: string Regenerates all nearby party members within 20 yards for 285 every 2 sec for 10 sec.  Druid must channel to maintain the spell.",
    ["GetTrainerServiceDescription(182)"] = "1: string Heals the target and their party for 679 over 7 sec. Party members must be within 43 yds of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.",
    ["GetTrainerServiceDescription(19)"] = "1: string Thorns sprout from the friendly target causing $w1 Nature damage to attackers when hit.  Lasts 10 min.",
    ["GetTrainerServiceDescription(2)"] = "1: string The druid roars, decreasing nearby enemies' melee attack power by 53.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(20)"] = "1: string Thorns sprout from the friendly target causing $w1 Nature damage to attackers when hit.  Lasts 10 min.",
